  useEffect(() => {
    // After mount, log the ref
    console.log('DatePicker ref:', datePickerRef.current);
    // Try to call focus() on it
    if (datePickerRef.current && typeof datePickerRef.current.focus === 'function') {
      datePickerRef.current.focus();
    }
  }, []);

  return (
    <div style={{ padding: '2rem' }}>
      <h1>Carbon DatePicker forwardRef repro</h1>
      {/* Attempt to pass a ref to the function component */}
      <DatePicker
        ref={datePickerRef}
        datePickerType="single"
        dateFormat="m/d/Y"
      >
        <DatePickerInput
          id="repro-date-picker"
          placeholder="mm/dd/yyyy"
          labelText="Select a date"
        />
      </DatePicker>
    </div>
  );
}

export default App;
